record.field:
action = False


def toast(title, message, kind='warning', sticky=False, next_action=False):
    params = {
        'title': title,
        'message': message,
        'type': kind,
        'sticky': sticky,
    }
    if next_action:
        params['next'] = next_action
    return {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': params}


def reload_permission(rec):
    view = env.ref('hr_employment_custom.view_employee_permission_form', raise_if_not_found=False)
    action = {
        'type': 'ir.actions.act_window',
        'name': rec.x_name or 'Employee Permission',
        'res_model': rec._name,
        'res_id': rec.id,
        'view_mode': 'form',
        'target': 'current',
    }
    if view:
        action['views'] = [(view.id, 'form')]
    return action


for rec in records.sudo():
    if rec.x_state in ('signature_requested', 'signed'):
        action = toast(
            'Generate PDF',
            'This permission has already entered the signature lifecycle. PDF regeneration is blocked.',
            'warning',
            True,
            reload_permission(rec),
        )
        continue

    employee = rec.x_employee_id.sudo() if rec.x_employee_id else False
    permission_type = rec.x_permission_type_id.sudo() if rec.x_permission_type_id else False

    if not employee:
        action = toast('Generate PDF', 'Cannot generate the permission form without a linked employee.', 'danger', True, reload_permission(rec))
        continue
    if not permission_type:
        action = toast('Generate PDF', 'Select a permission type before generating the form.', 'warning', True, reload_permission(rec))
        continue
    if not permission_type.x_form_code:
        action = toast('Generate PDF', 'The selected permission type is missing its form code.', 'warning', True, reload_permission(rec))
        continue
    if not rec.x_permission_date:
        action = toast('Generate PDF', 'Set the permission date before generating the form.', 'warning', True, reload_permission(rec))
        continue
    if not rec.x_time_from or not rec.x_time_to:
        action = toast('Generate PDF', 'Set both Time From and Time To before generating the form.', 'warning', True, reload_permission(rec))
        continue
    if not rec.x_reason:
        action = toast('Generate PDF', 'Enter the reason for request before generating the form.', 'warning', True, reload_permission(rec))
        continue

    generated_on = datetime.datetime.now()
    form_code = permission_type.x_form_code or rec.x_reference_code or 'MCEP-HR-PERM'
    form_title = permission_type.x_form_title or permission_type.x_name or 'Employee Permission'
    emp_part = employee.id if employee else 0

    document_reference = rec.x_document_reference
    if not document_reference:
        document_reference = '%s-EMP-%05d-%05d' % (form_code, emp_part, rec.id)

    vals = {
        'x_state': rec.x_state or 'draft',
        'x_reference_code': form_code,
        'x_document_reference': document_reference,
        'x_responsible_user_id': rec.x_responsible_user_id.id or env.user.id,
    }

    if employee.parent_id and employee.parent_id.user_id:
        vals['x_direct_manager_user_id'] = employee.parent_id.user_id.id

    if 'hr_responsible_id' in employee._fields and employee.hr_responsible_id:
        vals['x_hr_user_id'] = employee.hr_responsible_id.id
    elif not rec.x_hr_user_id:
        vals['x_hr_user_id'] = env.user.id

    normalized_name = '%s - %s - %s' % (
        employee.name or employee.display_name or 'Employee',
        form_title,
        document_reference,
    )
    vals['x_name'] = normalized_name

    rec.write(vals)
    rec = rec.sudo().browse(rec.id)

    report_xmlid = 'hr_employment_custom.action_report_mcep_employee_permission'
    pdf_content, _content_type = env['ir.actions.report'].sudo()._render_qweb_pdf(report_xmlid, [rec.id])

    filename = '%s - %s.pdf' % (rec.x_document_reference or form_code, form_title)

    attachment = env['ir.attachment'].sudo().create({
        'name': filename,
        'type': 'binary',
        'raw': pdf_content,
        'mimetype': 'application/pdf',
        'res_model': rec._name,
        'res_id': rec.id,
    })

    rec.write({
        'x_pdf_attachment_id': attachment.id,
        'x_generated_on': generated_on,
        'x_state': 'generated',
    })

    employee.message_post(
        body='تم توليد نموذج الإذن %s وربطه بسجل الموظف.' % form_code,
        subtype_xmlid='mail.mt_note',
        attachment_ids=[attachment.id],
    )

    action = toast('Generate PDF', '%s was generated and posted to the employee record.' % form_title, 'success', False, reload_permission(rec))
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

action = False
for rec in records.sudo():
    attachment = rec.x_pdf_attachment_id
    if attachment:
        action = {
            'type': 'ir.actions.act_url',
            'url': '/web/content/%s?download=true' % attachment.id,
            'target': 'self',
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Download Generated PDF',
                'message': 'No generated PDF is linked to this permission yet.',
                'type': 'warning',
                'sticky': False,
            }
        }
    break
if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

